/* protected pairs are sealed into a blob; plain pairs print normally */
struct oto {
    struct kv plain[8];          size_t nplain;
    unsigned char sealed[512];   size_t sealed_len;  /* nonce | ciphertext | tag */
    const char *mask[8];         size_t nmask;       /* protected field names */
};
int  oto_seal(struct oto *o, const unsigned char key[32]);   /* AES-256-GCM */
int  oto_open(struct oto *o, const unsigned char key[32]);
void oto_print(const struct oto *o, FILE *f);                /* plain partition only */
